                    case 'a':
                        numeric = false;
                        out += (lt.tm_hour >= 12) ? "PM" : "AM";
                        break;
                    case 'G':
                        numeric = false;
                        out += (lt.tm_year + 1900 > 0) ? "AD" : "BC";
                        break;
                    case 'z': case 'Z': case 'X':
                        numeric = false;
                        out += "+0000";
                        break;
                    default:
                        numeric = false;
                        out.append(n, c);
                        break;
